// Generated by OrchestKit Claude Plugin
// Created: 2026-08-21

// Single source of truth for the API versioning / deprecation / sunset policy.
// Rendered three ways from this one structure:
//   - /api-policy      → HTML page (crawlable, in the sitemap, linked in nav)
//   - /api-policy.md   → Markdown twin (unchanged URL, unchanged content)
//   - OpenAPI info.description + components.headers → machine-readable
//
// Why the HTML page was added: the Is Agentic audit reported "API versioning
// found (URL versioning) but no deprecation or sunset policy detected". The
// policy DID exist, at /api-policy.md, linked from llms.txt and advertised on
// every response as `Link: </api-policy.md>; rel="deprecation"`, but a crawler
// walking HTML pages and the sitemap could not see a Markdown-only document.
// The fix is a discoverable HTML representation of the SAME policy, not a
// second policy.

import { SITE } from "@/lib/constants";

export type PolicySection = {
	heading: string;
	/** Paragraphs rendered before the bullet list. */
	intro?: readonly string[];
	bullets?: readonly string[];
};

/** How long a deprecated endpoint is guaranteed to keep working. */
export const SUNSET_NOTICE_MONTHS = 6;

export const API_POLICY_TITLE = `${SITE.name} API versioning, deprecation & sunset policy`;

export const API_POLICY_LEAD = `The ${SITE.name} docs API is public, read-only, and free. This page states how it is versioned, how deprecations are announced, and what guarantees integrations can rely on.`;

export function apiPolicySections(): readonly PolicySection[] {
	const d = SITE.domain;
	return [
		{
			heading: "Versioning",
			bullets: [
				`The current API is **v1**, reachable both unversioned (\`${d}/api/*\`) and under the path-versioned alias (\`${d}/api/v1/*\`).`,
				"The unversioned path always tracks the latest version; pin `/api/v1/*` if you want path stability.",
				"**Breaking changes never ship in place.** They ship under a new `/api/vN` prefix; existing prefixes keep their behavior.",
				"Additive changes (new endpoints, new optional fields) ship continuously without a version bump.",
			],
		},
		{
			heading: "Deprecation",
			intro: ["Nothing is deprecated today. When an endpoint is deprecated:"],
			bullets: [
				"Its responses carry the RFC 8594 `Deprecation` header from the day of announcement.",
				`A \`Sunset\` header states the date after which the endpoint may stop responding, **at least ${SUNSET_NOTICE_MONTHS} months** after the deprecation announcement.`,
				'A `Link` header with `rel="deprecation"` points at migration notes.',
				`The deprecation is listed in the [changelog](${d}/docs/changelog) and on this page.`,
			],
		},
		{
			heading: "Sunset guarantees",
			bullets: [
				"Deprecated endpoints keep working until the `Sunset` date.",
				"After sunset, calls return `410 Gone` with an RFC 9457 problem body linking the replacement.",
			],
		},
		{
			heading: "Rate limits",
			intro: [
				"Every API response carries the IETF `RateLimit-*` headers so a client can pace itself without probing for the ceiling.",
			],
			bullets: [
				"`RateLimit-Policy`, `RateLimit-Limit`, `RateLimit-Remaining`, `RateLimit-Reset` on every response (legacy `X-RateLimit-*` twins included).",
				"Exceeding the window returns `429` with `Retry-After` and an RFC 9457 problem body.",
				"Limits are per IP, per endpoint, over a fixed 60-second window.",
			],
		},
		{
			heading: "Webhooks",
			intro: [
				`${SITE.name} **does not emit webhooks**, the API is read-only and request/response only, so there is no webhook registration, no event delivery, and consequently no webhook signing scheme. (Mentions of "webhooks" elsewhere in the docs refer to skill/agent content that helps you build webhooks in *your* applications.)`,
			],
		},
		{
			heading: "Stability of machine-readable surfaces",
			bullets: [
				`[OpenAPI spec](${d}/api/openapi), regenerated every release; schema-compatible within a major version.`,
				`[MCP server](${d}/api/mcp), tool names and shapes follow the same deprecation policy as REST endpoints.`,
				`[llms.txt](${d}/llms.txt) · [API catalog](${d}/.well-known/api-catalog) · [auth policy](${d}/auth.md)`,
			],
		},
	];
}

/** The policy as a standalone Markdown document (served at /api-policy.md). */
export function apiPolicyMarkdown(): string {
	const lines: string[] = [`# ${API_POLICY_TITLE}`, "", `> ${API_POLICY_LEAD}`, ""];
	for (const section of apiPolicySections()) {
		lines.push(`## ${section.heading}`, "");
		for (const p of section.intro ?? []) lines.push(p, "");
		for (const b of section.bullets ?? []) lines.push(`- ${b}`);
		if (section.bullets?.length) lines.push("");
	}
	return lines.join("\n");
}
